Revise the ConcIR candidate for the same requirements. The requirements and the frozen contract are authoritative; the feedback is repair context.

<domain_requirements>
Two workers A and B use two mutexes with an intermediate semaphore handshake, and an independent third task keeps making progress. Main starts all three. Every reachable state must still allow A and B to complete, and both workers must complete.
</domain_requirements>

<contract>
{
  "name": "partial-bystander",
  "properties": [
    {
      "kind": "deadlock_free",
      "id": "no-deadlock"
    },
    {
      "kind": "always_reachable",
      "id": "a-completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::a"
      }
    },
    {
      "kind": "always_reachable",
      "id": "b-completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::b"
      }
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::a completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::a"
      }
    },
    {
      "kind": "reachable",
      "description": "main::b completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::b"
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

